#include <memory>
#include <cassert>
#include <type_traits>
#include <utility>
struct Base {
    virtual ~Base() = default;
};
struct Derived : Base {};
int main() {
    std::auto_ptr<int> owner(new int(7));
    assert(*owner == 7 && *owner.get() == 7);
    std::auto_ptr<int> other(owner);
    assert(owner.get() == nullptr);
    owner = other;
    assert(other.get() == nullptr);
    int *raw = owner.release();
    assert(!owner.get());
    delete raw;
    owner.reset(new int(9));
    assert(*owner == 9);
    std::auto_ptr<Derived> derived(new Derived);
    std::auto_ptr<Base> base(derived);
    assert(base.get());
}
